package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.sun.net.httpserver.HttpServer;
import java.math.BigDecimal;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private record Received(String method, String path, String contentType, String body) {}

    private HttpServer provider;
    private final AtomicReference<Received> received = new AtomicReference<>();
    private volatile int status;
    private volatile String responseBody;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startProvider() throws Exception {
        provider = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        provider.createContext("/", exchange -> {
            var body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            received.set(new Received(
                    exchange.getRequestMethod(),
                    exchange.getRequestURI().getPath(),
                    exchange.getRequestHeaders().getFirst("Content-Type"),
                    body));
            var bytes = responseBody.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
            if (bytes.length > 0) exchange.getResponseBody().write(bytes);
            exchange.close();
        });
        provider.start();
        gateway = new HttpPaymentGateway(
                RestClient.builder().baseUrl("http://127.0.0.1:" + provider.getAddress().getPort()).build());
    }

    @AfterEach
    void stopProvider() {
        provider.stop(0);
    }

    private void providerAnswers(int status, String body) {
        this.status = status;
        this.responseBody = body;
    }

    private static final Money TWELVE_EUR = new Money(new BigDecimal("12.50"), "eur");

    @Test
    void it_posts_the_authorization_as_json_to_the_authorizations_endpoint() throws Exception {
        providerAnswers(200, "{\"status\":\"approved\"}");

        gateway.authorize("ORD-7", TWELVE_EUR);

        var request = received.get();
        assertThat(request.method()).isEqualTo("POST");
        assertThat(request.path()).isEqualTo("/v1/authorizations");
        assertThat(request.contentType()).startsWith("application/json");
        JsonNode json = new ObjectMapper().readTree(request.body());
        assertThat(json.fieldNames()).toIterable().containsExactlyInAnyOrder("reference", "amount", "currency");
        assertThat(json.get("reference").asText()).isEqualTo("ORD-7");
        assertThat(json.get("amount").isNumber()).isTrue();
        assertThat(json.get("amount").decimalValue()).isEqualByComparingTo("12.50");
        assertThat(json.get("currency").asText()).isEqualTo("EUR");
    }

    @Test
    void an_approved_answer_is_an_approval() {
        providerAnswers(200, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_a_decline() {
        providerAnswers(200, "{\"status\":\"declined\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void unknown_fields_in_the_answer_are_ignored() {
        providerAnswers(200, "{\"id\":\"auth_1\",\"status\":\"approved\",\"risk\":{\"score\":3}}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void an_unrecognised_status_is_never_treated_as_an_approval() {
        providerAnswers(200, "{\"status\":\"pending\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_an_approval() {
        providerAnswers(200, "{}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_refusal_with_402_is_a_decline() {
        providerAnswers(402, "{\"error\":\"card_refused\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_without_a_body_is_a_decline() {
        providerAnswers(402, "");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_that_claims_approval_is_still_a_decline() {
        providerAnswers(402, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_an_error_not_a_decline() {
        providerAnswers(400, "{\"error\":\"invalid_request\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-1", TWELVE_EUR))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_failure_is_an_error_not_a_decline() {
        providerAnswers(503, "");

        assertThatThrownBy(() -> gateway.authorize("ORD-1", TWELVE_EUR))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }
}
