    }

    @Test
    void an_answer_without_a_status_is_never_treated_as_an_approval() {
        providerAnswers(200, "{}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_refusal_with_402_is_a_decline() {
        providerAnswers(402, "{\"error\":\"card_refused\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_without_a_body_is_a_decline() {
        providerAnswers(402, "");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_that_claims_approval_is_still_a_decline() {
        providerAnswers(402, "{\"status\":\"approved\"}");

        assertThat(gateway.authorize("ORD-1", TWELVE_EUR)).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_an_error_not_a_decline() {
        providerAnswers(400, "{\"error\":\"invalid_request\"}");

        assertThatThrownBy(() -> gateway.authorize("ORD-1", TWELVE_EUR))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_failure_is_an_error_not_a_decline() {
        providerAnswers(503, "");

        assertThatThrownBy(() -> gateway.authorize("ORD-1", TWELVE_EUR))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }
}
